/* Bay Beach art for Daily Spin: the 1909 pavilion and the rides, traced from 3D models (cut from Home Base's art.js,
   Nov 5; the map's other buildings stay out of this public copy). */
window.LAKE_ART = window.LAKE_ART || {};
/* Bay Beach: the 1909 pavilion (traced from a 3D model built from Joey's photos and the original elevations)
   with the 100-foot Big Wheel behind it. o: { dim, dark, snowy, turning, lights, open, reduce } */
window.LAKE_ART.drawBayBeach = function (o) {
  const A = window.LAKE_ART.baybeach, P = (d, f, ex) => '<path d="' + d + '" fill="' + f + '"' + (ex || "") + "/>";
  const seam = (f, w) => ' stroke="' + f + '" stroke-width="' + (w || ".4") + '" stroke-linejoin="round" fill-rule="evenodd"';
  const n2 = (v) => Math.round(v * 10) / 10;
  let b = "", l = "";
  const hx = A.wheel.hub[0], hy = A.wheel.hub[1], R = A.wheel.r, gy = A.wheel.foot[1];
  const spin = o.turning && !o.reduce;
  const BLUE = "#2b5cb8", BLUE2 = "#1f4386", WHITE = "#f4f4f1", RED = "#c8323a", CAP = "#3d3f45";
  // legs: the back pair first, a little to the right, then the platform
  const legs = (dx, col, w) => {
    const top = hx + dx, sp = R * 0.56;
    return P("M" + n2(top - 1.2) + "," + n2(hy) + " L" + n2(top - sp - w) + "," + n2(gy) + " L" + n2(top - sp + w) + "," + n2(gy) + " L" + n2(top + 0.6) + "," + n2(hy + 3) + "Z", col) +
      P("M" + n2(top + 1.2) + "," + n2(hy) + " L" + n2(top + sp + w) + "," + n2(gy) + " L" + n2(top + sp - w) + "," + n2(gy) + " L" + n2(top - 0.6) + "," + n2(hy + 3) + "Z", col);
  };
  b += legs(3.2, BLUE2, 1.4);
  b += P("M" + n2(hx - R * 0.72) + "," + n2(gy) + " h" + n2(R * 1.5) + " v-2.6 h-" + n2(R * 1.5) + "z", "#cfcac0") + P("M" + n2(hx - 6) + "," + n2(gy - 2.6) + " h12 v-3.4 h-12z", "#bdb8ae");
  // the wheel: rim, spokes and gondolas, all in one group that turns when the park lights are on
  let wh = "";
  const N = 24;
  let spokes = "";
  for (let i = 0; i < N; i++) {
    const a = (i / N) * Math.PI * 2, ax = hx + Math.cos(a) * R * 0.94, ay = hy + Math.sin(a) * R * 0.94;
    const o1 = a + Math.PI / 2;
    spokes += "M" + n2(hx + Math.cos(o1) * 2.6) + "," + n2(hy + Math.sin(o1) * 2.6) + " L" + n2(ax) + "," + n2(ay) + " M" + n2(hx - Math.cos(o1) * 2.6) + "," + n2(hy - Math.sin(o1) * 2.6) + " L" + n2(ax) + "," + n2(ay) + " ";
  }
  wh += '<path d="' + spokes + '" stroke="' + WHITE + '" stroke-width=".55" fill="none" opacity=".95"/>';
  let truss = "";
  for (let i = 0; i < N * 2; i++) {
    const a0 = (i / (N * 2)) * Math.PI * 2, a1 = ((i + 1) / (N * 2)) * Math.PI * 2;
    const r0 = i % 2 ? R : R * 0.92, r1 = i % 2 ? R * 0.92 : R;
    truss += "M" + n2(hx + Math.cos(a0) * r0) + "," + n2(hy + Math.sin(a0) * r0) + " L" + n2(hx + Math.cos(a1) * r1) + "," + n2(hy + Math.sin(a1) * r1) + " ";
  }
  wh += '<circle cx="' + n2(hx) + '" cy="' + n2(hy) + '" r="' + n2(R) + '" fill="none" stroke="' + WHITE + '" stroke-width="1.5"/>' +
    '<circle cx="' + n2(hx) + '" cy="' + n2(hy) + '" r="' + n2(R * 0.92) + '" fill="none" stroke="' + WHITE + '" stroke-width="1"/>' +
    '<path d="' + truss + '" stroke="' + WHITE + '" stroke-width=".5" fill="none"/>';
  if (o.lights) {
    let bl = "";
    for (let i = 0; i < N * 2; i++) { const a = (i / (N * 2)) * Math.PI * 2; bl += '<circle cx="' + n2(hx + Math.cos(a) * R * 0.96) + '" cy="' + n2(hy + Math.sin(a) * R * 0.96) + '" r=".8" fill="#fff3c4"/>'; }
    if (o.dark) {
      let led = "";
      for (let i = 0; i < N; i++) { const a = (i / N) * Math.PI * 2; led += '<path d="M' + n2(hx + Math.cos(a) * 4) + "," + n2(hy + Math.sin(a) * 4) + " L" + n2(hx + Math.cos(a) * R * 0.9) + "," + n2(hy + Math.sin(a) * R * 0.9) + '" stroke="hsl(' + Math.round((i / N) * 360) + ',90%,66%)" stroke-width="1" opacity=".85"/>'; }
      wh += led + '<circle cx="' + n2(hx) + '" cy="' + n2(hy) + '" r="' + n2(R * 1.08) + '" fill="url(#gGlow)" opacity=".45"/>';
    }
    wh += bl;
  }
  // gondolas hang from the rim and stay upright while the wheel turns
  for (let i = 0; i < N; i++) {
    const a = (i / N) * Math.PI * 2 + Math.PI / N, px = hx + Math.cos(a) * R, py = hy + Math.sin(a) * R;
    let g = '<path d="M0,0 V1.4" stroke="' + WHITE + '" stroke-width=".6"/>' + P("M-3.1,3 Q0,0.6 3.1,3 Z", CAP) + P("M-2.7,3 h5.4 v4.4 q0,1.6 -1.6,1.6 h-2.2 q-1.6,0 -1.6,-1.6z", RED) + P("M-2.2,3.9 h4.4 v1.6 h-4.4z", o.dim && o.lights ? "#ffd98a" : "#5a2a2e");
    g = spin ? '<g><animateTransform attributeName="transform" type="rotate" from="0 0 0" to="-360 0 0" dur="96s" repeatCount="indefinite"/>' + g + "</g>" : g;
    wh += '<g transform="translate(' + n2(px) + "," + n2(py) + ')">' + g + "</g>";
  }
  b += "<g>" + (spin ? '<animateTransform attributeName="transform" type="rotate" from="0 ' + n2(hx) + " " + n2(hy) + '" to="360 ' + n2(hx) + " " + n2(hy) + '" dur="96s" repeatCount="indefinite"/>' : "") + wh + "</g>";
  b += legs(0, BLUE, 1.6) + '<circle cx="' + n2(hx) + '" cy="' + n2(hy) + '" r="2.6" fill="' + WHITE + '"/><circle cx="' + n2(hx) + '" cy="' + n2(hy) + '" r="1.2" fill="' + BLUE2 + '"/>';
  if (o.lights && o.dim) l += '<circle cx="' + n2(hx) + '" cy="' + n2(hy) + '" r="' + n2(R * 1.25) + '" fill="url(#gGlow)" opacity=".35"/>';
  // the pavilion
  A.shapes.forEach((s) => {
    let f = s[1];
    if (o.snowy && s[0] === "roof") f = parseInt(f.slice(1, 3), 16) > 0x70 ? "#f6f8fa" : "#dfe6ec";
    if (o.snowy && s[0] === "dome") f = parseInt(f.slice(1, 3), 16) > 0x40 ? "#eef3f6" : "#c9d5dc";
    b += P(s[2], f, seam(f));
  });
  let r = 7; const rnd = () => { r = (r * 1664525 + 1013904223) % 4294967296; return r / 4294967296; };
  A.wins.forEach((w) => { b += P(w[0], w[1], seam(w[1], ".3")); if (o.dim && (o.open || rnd() < 0.3)) l += P(w[0], o.open ? "#ffd98a" : "#f5c97a", ' fill-rule="evenodd" opacity="' + (o.open ? 0.95 : 0.6) + '"'); });
  b += P(A.shadow, "#24323a", ' opacity=".15" fill-rule="evenodd"');
  if (o.dim && o.open) l += '<circle cx="0" cy="-22" r="70" fill="url(#gGlow)" opacity=".35"/>';
  // the flag over the cupola
  const fl = A.flag;
  b += '<path d="M' + fl[0] + "," + fl[1] + " L" + fl[2] + "," + fl[3] + '" stroke="#8d8c88" stroke-width=".8"/>' +
    '<g transform="translate(' + fl[2] + "," + fl[3] + ')' + (o.windFlip ? ' scale(-1,1)' : '') + '"><rect width="8" height="5" fill="#f4f1ea"/><rect y="1.1" width="8" height=".9" fill="#b8352c"/><rect y="3" width="8" height=".9" fill="#b8352c"/><rect y="4.6" width="8" height=".5" fill="#b8352c"/><rect width="3.4" height="2.6" fill="#2f4a7a"/></g>';
  return { b, l };
};

window.LAKE_ART = window.LAKE_ART || {};
LAKE_ART.models = LAKE_ART.models || {};
LAKE_ART._h = (function () {
  const n2 = (v) => Math.round(v * 100) / 100;
  const attr = (ex) => (ex ? " " + ex : "");
  const H = {
    P: (d, f, ex) => '<path d="' + d + '" fill="' + f + '"' + (ex || "") + "/>",
    seam: (f, w) => ' stroke="' + f + '" stroke-width="' + (w || ".4") + '" stroke-linejoin="round" fill-rule="evenodd"',
    rect: (x, y, w, h, f, ex) => '<rect x="' + n2(x) + '" y="' + n2(y) + '" width="' + n2(w) + '" height="' + n2(h) + '" fill="' + f + '"' + attr(ex) + "/>",
    circ: (x, y, r, f, ex) => '<circle cx="' + n2(x) + '" cy="' + n2(y) + '" r="' + n2(r) + '" fill="' + f + '"' + attr(ex) + "/>",
    ell: (x, y, rx, ry, f, ex) => '<ellipse cx="' + n2(x) + '" cy="' + n2(y) + '" rx="' + n2(rx) + '" ry="' + n2(ry) + '" fill="' + f + '"' + attr(ex) + "/>",
    path: (d, f, ex) => '<path d="' + d + '" fill="' + f + '"' + attr(ex) + "/>",
    line: (d, s, w, ex) => '<path d="' + d + '" fill="none" stroke="' + s + '" stroke-width="' + w + '"' + attr(ex) + "/>",
    text: (x, y, s, size, f, ex) => '<text x="' + n2(x) + '" y="' + n2(y) + '" font-size="' + n2(size) + '" fill="' + f + '" text-anchor="middle" ' + (ex || 'font-family="Figtree, sans-serif" font-weight="700"') + ">" + String(s == null ? "" : s).replace(/[&<>"']/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch])) + "</text>",
    mat: (m, inner) => (inner ? '<g transform="matrix(' + m.join(" ") + ')">' + inner + "</g>" : ""),
    rgb: (h) => { h = h.replace("#", ""); const v = parseInt(h, 16); return [(v >> 16) & 255, (v >> 8) & 255, v & 255]; },
    lum: (h) => { const c = H.rgb(h); return 0.3 * c[0] + 0.59 * c[1] + 0.11 * c[2]; },
    shade: (h, t) => { const c = H.rgb(h), to = t < 0 ? 0 : 255, k = Math.abs(t); return "#" + c.map((v) => Math.round(v + (to - v) * k).toString(16).padStart(2, "0")).join(""); },
    snow: (f) => { const v = H.lum(f); return v > 72 ? "#f6f8fa" : v > 58 ? "#e6ecf1" : "#d5dee6"; },
  };
  return H;
})();

